sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    try {

        // ---------------------------------------------------------
        // CREATE CAMPUSDESK AI ENGINE
        // ---------------------------------------------------------

        var aiEngine = new CampusDeskAIRecommendationEngine();


        // ---------------------------------------------------------
        // ANALYZE CURRENT INCIDENT
        // ---------------------------------------------------------

        var result = aiEngine.analyzeIncident(current);


        // ---------------------------------------------------------
        // EXISTING AI ANALYSIS
        // ---------------------------------------------------------

        // AI Suggested Category
        current.setValue(
            'u_ai_suggested_category',
            result.suggested_category
        );


        // AI Confidence
        current.setValue(
            'u_ai_confidence',
            result.confidence
        );


        // AI Recommendation
        current.setValue(
            'x_1971543_campus_0_ai_recommendation',
            result.recommendation
        );


        // ---------------------------------------------------------
        // KNOWLEDGE ARTICLE
        // ---------------------------------------------------------

        if (result.knowledge_article) {

            current.setValue(
                'u_knowledge_article',
                result.knowledge_article
            );
        }


        // ---------------------------------------------------------
        // AI PRIORITY INTELLIGENCE
        // ---------------------------------------------------------

        // AI Suggested Impact
        if (result.suggested_impact) {

            current.setValue(
                'x_1971543_campus_0_ai_suggested_impact',
                result.suggested_impact
            );
        }


        // AI Suggested Urgency
        if (result.suggested_urgency) {

            current.setValue(
                'x_1971543_campus_0_ai_suggested_urgency',
                result.suggested_urgency
            );
        }


        // AI Suggested Priority
        if (result.suggested_priority) {

            current.setValue(
                'x_1971543_campus_0_ai_suggested_priority',
                result.suggested_priority
            );
        }


        // AI Priority Reason
        if (result.priority_reason) {

            current.setValue(
                'x_1971543_campus_0_ai_priority_reason',
                result.priority_reason
            );
        }


        // ---------------------------------------------------------
        // AI RESOLUTION INTELLIGENCE
        // ---------------------------------------------------------

        // AI Resolution Guidance
        //
        // IMPORTANT:
        // Actual field name:
        // x_1971543_campus_0_ai_resolution_guidance
        //

        if (result.resolution_guidance) {

            current.setValue(
                'x_1971543_campus_0_ai_resolution_guidance',
                result.resolution_guidance
            );
        }


        // ---------------------------------------------------------
        // LOGGING
        // ---------------------------------------------------------

        gs.info(
            '[CampusDesk AI] Incident analyzed - ' +
            'Category: ' + result.suggested_category +
            ', Confidence: ' + result.confidence +
            ', Impact: ' + result.suggested_impact +
            ', Urgency: ' + result.suggested_urgency +
            ', Priority: ' + result.suggested_priority +
            ', Knowledge Article: ' + result.knowledge_article +
            ', Resolution Guidance: ' +
            (result.resolution_guidance ? 'Generated' : 'Not Generated')
        );


    } catch (ex) {

        gs.error(
            '[CampusDesk AI] Error analyzing Incident: ' +
            ex.message
        );
    }

})(current, previous);
